def compute(vars):
    value_2019 = vars["v1"]
    value_2018 = vars["v2"]
    change = value_2019 - value_2018

    return {
        "value": change,
        "trace": {
            "value_2019": value_2019,
            "value_2018": value_2018,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "currency"
            }
        }
    }
